//! The platform-neutral driver contract every backend implements.
//!
//! All coordinates crossing this boundary are **device pixels** of the
//! captured display (the pixel grid of the screenshot the driver returned).
//! Backends that post input in other units (macOS points, Windows normalized
//! absolute coordinates) convert internally using the scale they reported in
//! [`TargetInfo`].

use std::fmt;

use crate::keys::KeyCombo;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Button {
    Left,
    Right,
    Middle,
}

impl Button {
    pub fn parse(value: &str) -> Result<Self, String> {
        match value.to_ascii_lowercase().as_str() {
            "left" | "" => Ok(Self::Left),
            "right" => Ok(Self::Right),
            "middle" => Ok(Self::Middle),
            other => Err(format!(
                "unknown button `{other}`; expected left, right, or middle"
            )),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ScrollDir {
    Up,
    Down,
    Left,
    Right,
}

impl ScrollDir {
    pub fn parse(value: &str) -> Result<Self, String> {
        match value.to_ascii_lowercase().as_str() {
            "up" => Ok(Self::Up),
            "down" => Ok(Self::Down),
            "left" => Ok(Self::Left),
            "right" => Ok(Self::Right),
            other => Err(format!(
                "unknown scroll direction `{other}`; expected up, down, left, or right"
            )),
        }
    }
}

/// A point in device pixels.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Point {
    pub x: f64,
    pub y: f64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TargetKind {
    Desktop,
    Android,
    Harmony,
}

impl TargetKind {
    pub fn label(self) -> &'static str {
        match self {
            Self::Desktop => "desktop",
            Self::Android => "android",
            Self::Harmony => "harmony",
        }
    }
}

/// What the model is told about the target in `computer_info`.
#[derive(Debug, Clone)]
pub struct TargetInfo {
    pub kind: TargetKind,
    /// Human-readable backend name, e.g. `macos-coregraphics`, `adb`.
    pub driver: String,
    /// Captured display size in device pixels.
    pub device_w: u32,
    pub device_h: u32,
    /// Free-form diagnostics: permissions, helper binaries found, device id.
    pub notes: Vec<String>,
    pub supports_ui_tree: bool,
    pub supports_apps: bool,
}

/// An encoded screenshot straight from the backend (PNG or JPEG bytes).
#[derive(Debug, Clone)]
pub struct RawFrame {
    pub bytes: Vec<u8>,
}

/// One interactive element from an accessibility/layout dump.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UiNode {
    pub class: String,
    /// Visible text or content description.
    pub label: String,
    /// Resource id / component id when present.
    pub id: String,
    /// `(left, top, right, bottom)` in device pixels.
    pub bounds: (u32, u32, u32, u32),
    pub clickable: bool,
    pub scrollable: bool,
    pub editable: bool,
    pub focused: bool,
    pub depth: u8,
}

impl UiNode {
    pub fn center(&self) -> (u32, u32) {
        let (l, t, r, b) = self.bounds;
        ((l + r) / 2, (t + b) / 2)
    }

    pub fn is_interesting(&self) -> bool {
        self.clickable
            || self.scrollable
            || self.editable
            || self.focused
            || !self.label.trim().is_empty()
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AppAction<'a> {
    Launch(&'a str),
    List,
    Current,
}

#[derive(Debug)]
pub enum DriverError {
    /// The backend cannot do this on this target (e.g. UI tree on desktop).
    Unsupported(String),
    /// A helper binary or device is missing; message names the fix.
    Unavailable(String),
    /// The OS refused (permissions).
    Permission(String),
    /// Anything else, already phrased for the operator.
    Failed(String),
}

impl fmt::Display for DriverError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Unsupported(m) => write!(f, "unsupported on this target: {m}"),
            Self::Unavailable(m) => write!(f, "unavailable: {m}"),
            Self::Permission(m) => write!(f, "permission denied: {m}"),
            Self::Failed(m) => write!(f, "{m}"),
        }
    }
}

impl std::error::Error for DriverError {}

impl DriverError {
    pub fn failed(msg: impl Into<String>) -> Self {
        Self::Failed(msg.into())
    }
}

pub trait Driver {
    fn info(&mut self) -> Result<TargetInfo, DriverError>;
    fn screenshot(&mut self) -> Result<RawFrame, DriverError>;
    fn move_to(&mut self, p: Point) -> Result<(), DriverError>;
    /// `clicks` is 1..=3; `hold_ms > 0` means press-and-hold (long press).
    fn click(&mut self, p: Point, button: Button, clicks: u32, hold_ms: u64) -> Result<(), DriverError>;
    fn drag(&mut self, from: Point, to: Point, duration_ms: u64) -> Result<(), DriverError>;
    /// `amount` is in notches (desktop) or roughly half-screens/5 (devices).
    fn scroll(&mut self, p: Point, dir: ScrollDir, amount: u32) -> Result<(), DriverError>;
    fn type_text(&mut self, text: &str) -> Result<(), DriverError>;
    fn key(&mut self, combo: &KeyCombo) -> Result<(), DriverError>;
    fn ui_tree(&mut self) -> Result<Vec<UiNode>, DriverError>;
    fn app(&mut self, action: AppAction<'_>) -> Result<String, DriverError>;
    fn devices(&mut self) -> Result<String, DriverError>;
}

//! Platform-neutral key names and `ctrl+shift+t` style combo parsing.
//!
//! The model speaks one vocabulary on every target; each driver maps
//! [`NamedKey`] to its own key codes and decides what `Meta` means (Command
//! on macOS, Windows key on Windows, Super on Linux; ignored on devices).

use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Modifiers {
    pub ctrl: bool,
    pub alt: bool,
    pub shift: bool,
    pub meta: bool,
}

impl Modifiers {
    pub fn any(self) -> bool {
        self.ctrl || self.alt || self.shift || self.meta
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NamedKey {
    Enter,
    Tab,
    Escape,
    Backspace,
    Delete,
    Space,
    Up,
    Down,
    Left,
    Right,
    Home,
    End,
    PageUp,
    PageDown,
    Insert,
    CapsLock,
    F(u8),
    // Device / media keys.
    Back,
    AppHome,
    Recents,
    Power,
    VolumeUp,
    VolumeDown,
    Menu,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Key {
    Named(NamedKey),
    /// A printable character; drivers pick the key code from their layout
    /// table and add Shift where the character requires it.
    Char(char),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct KeyCombo {
    pub modifiers: Modifiers,
    pub key: Key,
}

impl fmt::Display for KeyCombo {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut parts: Vec<String> = Vec::new();
        if self.modifiers.ctrl {
            parts.push("ctrl".into());
        }
        if self.modifiers.alt {
            parts.push("alt".into());
        }
        if self.modifiers.shift {
            parts.push("shift".into());
        }
        if self.modifiers.meta {
            parts.push("meta".into());
        }
        parts.push(match self.key {
            Key::Named(named) => named_key_name(named).to_string(),
            Key::Char(c) => c.to_string(),
        });
        write!(f, "{}", parts.join("+"))
    }
}

pub const KEY_NAMES: &[&str] = &[
    "enter", "tab", "esc", "backspace", "delete", "space", "up", "down", "left", "right", "home",
    "end", "pageup", "pagedown", "insert", "capslock", "f1..f24", "back", "apphome", "recents",
    "power", "volume_up", "volume_down", "menu",
];

pub const MODIFIER_NAMES: &[&str] = &["ctrl", "alt", "shift", "meta"];

fn named_key_name(key: NamedKey) -> &'static str {
    match key {
        NamedKey::Enter => "enter",
        NamedKey::Tab => "tab",
        NamedKey::Escape => "esc",
        NamedKey::Backspace => "backspace",
        NamedKey::Delete => "delete",
        NamedKey::Space => "space",
        NamedKey::Up => "up",
        NamedKey::Down => "down",
        NamedKey::Left => "left",
        NamedKey::Right => "right",
        NamedKey::Home => "home",
        NamedKey::End => "end",
        NamedKey::PageUp => "pageup",
        NamedKey::PageDown => "pagedown",
        NamedKey::Insert => "insert",
        NamedKey::CapsLock => "capslock",
        NamedKey::F(_) => "f<n>",
        NamedKey::Back => "back",
        NamedKey::AppHome => "apphome",
        NamedKey::Recents => "recents",
        NamedKey::Power => "power",
        NamedKey::VolumeUp => "volume_up",
        NamedKey::VolumeDown => "volume_down",
        NamedKey::Menu => "menu",
    }
}

fn parse_named(token: &str) -> Option<NamedKey> {
    let key = match token {
        "enter" | "return" | "ret" => NamedKey::Enter,
        "tab" => NamedKey::Tab,
        "esc" | "escape" => NamedKey::Escape,
        "backspace" | "bs" => NamedKey::Backspace,
        "delete" | "del" | "forwarddelete" => NamedKey::Delete,
        "space" | "spacebar" => NamedKey::Space,
        "up" | "arrowup" => NamedKey::Up,
        "down" | "arrowdown" => NamedKey::Down,
        "left" | "arrowleft" => NamedKey::Left,
        "right" | "arrowright" => NamedKey::Right,
        "home" => NamedKey::Home,
        "end" => NamedKey::End,
        "pageup" | "pgup" => NamedKey::PageUp,
        "pagedown" | "pgdn" | "pgdown" => NamedKey::PageDown,
        "insert" | "ins" => NamedKey::Insert,
        "capslock" => NamedKey::CapsLock,
        "back" => NamedKey::Back,
        "apphome" | "homescreen" => NamedKey::AppHome,
        "recents" | "appswitch" | "app_switch" | "overview" => NamedKey::Recents,
        "power" => NamedKey::Power,
        "volume_up" | "volumeup" | "vol_up" => NamedKey::VolumeUp,
        "volume_down" | "volumedown" | "vol_down" => NamedKey::VolumeDown,
        "menu" => NamedKey::Menu,
        _ => {
            let digits = token.strip_prefix('f')?;
            let n: u8 = digits.parse().ok()?;
            if (1..=24).contains(&n) {
                NamedKey::F(n)
            } else {
                return None;
            }
        }
    };
    Some(key)
}

/// Parse `"ctrl+shift+t"`, `"Cmd+a"`, `"enter"`, `"back"`, or a literal `"+"`.
///
/// Tokens are separated by `+`; a trailing empty token means the literal
/// plus sign (`"ctrl++"` is Ctrl and `+`). Modifier aliases: `cmd`, `command`,
/// `super`, `win`, `windows`, `meta` → meta; `option`, `opt`, `alt` → alt;
/// `control`, `ctl`, `ctrl` → ctrl; `shift` → shift.
pub fn parse_combo(input: &str) -> Result<KeyCombo, String> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Err("keys must not be empty".to_string());
    }
    if trimmed == "+" {
        return Ok(KeyCombo {
            modifiers: Modifiers::default(),
            key: Key::Char('+'),
        });
    }
    let mut modifiers = Modifiers::default();
    let mut key: Option<Key> = None;
    let mut tokens: Vec<&str> = trimmed.split('+').collect();
    // "ctrl++" splits into ["ctrl", "", ""]: fold the two empties into "+".
    if tokens.len() >= 2
        && tokens[tokens.len() - 1].is_empty()
        && tokens[tokens.len() - 2].is_empty()
    {
        tokens.truncate(tokens.len() - 2);
        tokens.push("+");
    }
    for raw in tokens {
        let token = raw.trim();
        if token.is_empty() {
            return Err(format!("malformed key combo `{input}`"));
        }
        let lower = token.to_ascii_lowercase();
        match lower.as_str() {
            "ctrl" | "control" | "ctl" => modifiers.ctrl = true,
            "alt" | "option" | "opt" => modifiers.alt = true,
            "shift" => modifiers.shift = true,
            "meta" | "cmd" | "command" | "super" | "win" | "windows" => modifiers.meta = true,
            _ => {
                if key.is_some() {
                    return Err(format!(
                        "key combo `{input}` names more than one non-modifier key"
                    ));
                }
                if let Some(named) = parse_named(&lower) {
                    key = Some(Key::Named(named));
                } else if token.chars().count() == 1 {
                    key = Some(Key::Char(token.chars().next().unwrap_or(' ')));
                } else {
                    return Err(format!(
                        "unknown key `{token}`; modifiers: {}; keys: {} or a single character",
                        MODIFIER_NAMES.join(", "),
                        KEY_NAMES.join(", ")
                    ));
                }
            }
        }
    }
    let key = key.ok_or_else(|| {
        format!("key combo `{input}` has only modifiers; add a key such as `a` or `enter`")
    })?;
    Ok(KeyCombo { modifiers, key })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_modifier_combo() {
        let combo = parse_combo("ctrl+shift+t").unwrap();
        assert!(combo.modifiers.ctrl && combo.modifiers.shift);
        assert!(!combo.modifiers.alt && !combo.modifiers.meta);
        assert_eq!(combo.key, Key::Char('t'));
    }

    #[test]
    fn parses_cmd_alias_case_insensitively() {
        let combo = parse_combo("Cmd+A").unwrap();
        assert!(combo.modifiers.meta);
        assert_eq!(combo.key, Key::Char('A'));
    }

    #[test]
    fn parses_named_and_device_keys() {
        assert_eq!(parse_combo("enter").unwrap().key, Key::Named(NamedKey::Enter));
        assert_eq!(parse_combo("Back").unwrap().key, Key::Named(NamedKey::Back));
        assert_eq!(parse_combo("f12").unwrap().key, Key::Named(NamedKey::F(12)));
        assert_eq!(
            parse_combo("volume_up").unwrap().key,
            Key::Named(NamedKey::VolumeUp)
        );
    }

    #[test]
    fn parses_literal_plus() {
        assert_eq!(parse_combo("+").unwrap().key, Key::Char('+'));
        let combo = parse_combo("ctrl++").unwrap();
        assert!(combo.modifiers.ctrl);
        assert_eq!(combo.key, Key::Char('+'));
    }

    #[test]
    fn rejects_unknown_and_modifier_only() {
        let err = parse_combo("ctrl+launch").unwrap_err();
        assert!(err.contains("unknown key `launch`"), "{err}");
        assert!(err.contains("enter"));
        let err = parse_combo("ctrl+shift").unwrap_err();
        assert!(err.contains("only modifiers"), "{err}");
        assert!(parse_combo("").is_err());
        assert!(parse_combo("a+b").is_err());
    }

    #[test]
    fn display_round_trips() {
        assert_eq!(parse_combo("ctrl+shift+t").unwrap().to_string(), "ctrl+shift+t");
        assert_eq!(parse_combo("cmd+enter").unwrap().to_string(), "meta+enter");
    }
}

//! Server configuration: `~/.codewhale/computer-use.toml` plus CLI overrides.
//!
//! Plugin-spawned children run with a scrubbed environment
//! (`crates/tui/src/child_env.rs` keeps PATH/HOME and little else), so the
//! file is the durable way to pick a device target; environment variables are
//! honored only as a convenience when they happen to be present.

use std::path::{Path, PathBuf};

use serde::Deserialize;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Target {
    #[default]
    Auto,
    Desktop,
    Android,
    Harmony,
}

impl Target {
    pub fn parse(value: &str) -> Result<Self, String> {
        match value.trim().to_ascii_lowercase().as_str() {
            "auto" | "" => Ok(Self::Auto),
            "desktop" | "host" | "native" | "macos" | "windows" | "linux" => Ok(Self::Desktop),
            "android" | "adb" => Ok(Self::Android),
            "harmony" | "harmonyos" | "ohos" | "openharmony" | "hdc" => Ok(Self::Harmony),
            other => Err(format!(
                "unknown target `{other}`; expected auto, desktop, android, or harmony"
            )),
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Self::Auto => "auto",
            Self::Desktop => "desktop",
            Self::Android => "android",
            Self::Harmony => "harmony",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Mode {
    /// Screenshots and input.
    #[default]
    Act,
    /// Screenshots, zoom, info, UI tree, devices only.
    Observe,
}

impl Mode {
    pub fn parse(value: &str) -> Result<Self, String> {
        match value.trim().to_ascii_lowercase().as_str() {
            "act" | "" | "full" => Ok(Self::Act),
            "observe" | "read-only" | "readonly" | "view" => Ok(Self::Observe),
            other => Err(format!("unknown mode `{other}`; expected act or observe")),
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Self::Act => "act",
            Self::Observe => "observe",
        }
    }
}

pub const DEFAULT_MAX_EDGE: u32 = 1024;
pub const MIN_MAX_EDGE: u32 = 256;
pub const MAX_MAX_EDGE: u32 = 2048;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Config {
    pub target: Target,
    pub mode: Mode,
    /// Longest edge of screenshots sent to the model, in pixels.
    pub max_edge: u32,
    pub grid_default: bool,
    pub screenshot_after_action: bool,
    /// Settle delay before the post-action screenshot (desktop / device).
    pub settle_ms_desktop: u64,
    pub settle_ms_device: u64,
    pub android: AndroidConfig,
    pub harmony: HarmonyConfig,
    pub linux: LinuxConfig,
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct AndroidConfig {
    /// `adb -s <serial>`; empty = the only connected device.
    pub serial: String,
    /// Explicit adb path; empty = search PATH and SDK locations.
    pub adb: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct HarmonyConfig {
    /// `hdc -t <key>`; empty = the only connected target.
    pub target: String,
    pub hdc: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct LinuxConfig {
    /// X11 display used when the environment does not provide one.
    pub display: String,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            target: Target::Auto,
            mode: Mode::Act,
            max_edge: DEFAULT_MAX_EDGE,
            grid_default: false,
            screenshot_after_action: true,
            settle_ms_desktop: 300,
            settle_ms_device: 700,
            android: AndroidConfig::default(),
            harmony: HarmonyConfig::default(),
            linux: LinuxConfig::default(),
        }
    }
}

#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct FileConfig {
    target: Option<String>,
    mode: Option<String>,
    max_edge: Option<u32>,
    grid: Option<bool>,
    screenshot_after_action: Option<bool>,
    settle_ms_desktop: Option<u64>,
    settle_ms_device: Option<u64>,
    #[serde(default)]
    android: FileAndroid,
    #[serde(default)]
    harmony: FileHarmony,
    #[serde(default)]
    linux: FileLinux,
}

#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct FileAndroid {
    serial: Option<String>,
    adb: Option<String>,
}

#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct FileHarmony {
    target: Option<String>,
    hdc: Option<String>,
}

#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct FileLinux {
    display: Option<String>,
}

/// Where the config file lives: `$CODEWHALE_HOME/computer-use.toml` or
/// `~/.codewhale/computer-use.toml`.
pub fn default_config_path() -> Option<PathBuf> {
    if let Ok(home) = std::env::var("CODEWHALE_HOME")
        && !home.trim().is_empty()
    {
        return Some(PathBuf::from(home).join("computer-use.toml"));
    }
    home_dir().map(|home| home.join(".codewhale").join("computer-use.toml"))
}

pub fn home_dir() -> Option<PathBuf> {
    std::env::var_os("HOME")
        .or_else(|| std::env::var_os("USERPROFILE"))
        .map(PathBuf::from)
        .filter(|p| !p.as_os_str().is_empty())
}

impl Config {
    /// Defaults, then the file (if present), then environment hints.
    pub fn load(path: Option<&Path>) -> Result<Self, String> {
        let mut cfg = Self::default();
        let path = match path {
            Some(p) => Some(p.to_path_buf()),
            None => default_config_path(),
        };
        if let Some(path) = path
            && path.is_file()
        {
            let text = std::fs::read_to_string(&path)
                .map_err(|e| format!("failed to read {}: {e}", path.display()))?;
            cfg.apply_toml(&text)
                .map_err(|e| format!("invalid {}: {e}", path.display()))?;
        }
        cfg.apply_env();
        cfg.validate()?;
        Ok(cfg)
    }

    pub fn apply_toml(&mut self, text: &str) -> Result<(), String> {
        let file: FileConfig = toml::from_str(text).map_err(|e| e.to_string())?;
        if let Some(target) = file.target {
            self.target = Target::parse(&target)?;
        }
        if let Some(mode) = file.mode {
            self.mode = Mode::parse(&mode)?;
        }
        if let Some(max_edge) = file.max_edge {
            self.max_edge = max_edge;
        }
        if let Some(grid) = file.grid {
            self.grid_default = grid;
        }
        if let Some(v) = file.screenshot_after_action {
            self.screenshot_after_action = v;
        }
        if let Some(v) = file.settle_ms_desktop {
            self.settle_ms_desktop = v;
        }
        if let Some(v) = file.settle_ms_device {
            self.settle_ms_device = v;
        }
        if let Some(v) = file.android.serial {
            self.android.serial = v;
        }
        if let Some(v) = file.android.adb {
            self.android.adb = v;
        }
        if let Some(v) = file.harmony.target {
            self.harmony.target = v;
        }
        if let Some(v) = file.harmony.hdc {
            self.harmony.hdc = v;
        }
        if let Some(v) = file.linux.display {
            self.linux.display = v;
        }
        Ok(())
    }

    /// Environment hints (only consulted when the value is present).
    fn apply_env(&mut self) {
        if self.android.serial.is_empty()
            && let Ok(serial) = std::env::var("ANDROID_SERIAL")
            && !serial.trim().is_empty()
        {
            self.android.serial = serial.trim().to_string();
        }
        if let Ok(mode) = std::env::var("CODEWHALE_COMPUTER_USE_MODE")
            && let Ok(mode) = Mode::parse(&mode)
        {
            self.mode = mode;
        }
        if let Ok(target) = std::env::var("CODEWHALE_COMPUTER_USE_TARGET")
            && let Ok(target) = Target::parse(&target)
        {
            self.target = target;
        }
    }

    pub fn validate(&self) -> Result<(), String> {
        if !(MIN_MAX_EDGE..=MAX_MAX_EDGE).contains(&self.max_edge) {
            return Err(format!(
                "max_edge must be between {MIN_MAX_EDGE} and {MAX_MAX_EDGE}, got {}",
                self.max_edge
            ));
        }
        if self.settle_ms_desktop > 10_000 || self.settle_ms_device > 10_000 {
            return Err("settle delays must be at most 10000 ms".to_string());
        }
        Ok(())
    }

    /// Resolve `auto` using compile-time target and configured devices.
    pub fn effective_target(&self) -> Target {
        match self.target {
            Target::Auto => {
                if cfg!(target_os = "android") {
                    Target::Android
                } else if cfg!(target_env = "ohos") {
                    Target::Harmony
                } else if !self.android.serial.is_empty() {
                    Target::Android
                } else if !self.harmony.target.is_empty() {
                    Target::Harmony
                } else {
                    Target::Desktop
                }
            }
            explicit => explicit,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn defaults_are_sane() {
        let cfg = Config::default();
        assert_eq!(cfg.max_edge, DEFAULT_MAX_EDGE);
        assert_eq!(cfg.mode, Mode::Act);
        assert!(cfg.screenshot_after_action);
        cfg.validate().unwrap();
    }

    #[test]
    fn toml_overrides_apply() {
        let mut cfg = Config::default();
        cfg.apply_toml(
            r#"
target = "android"
mode = "observe"
max_edge = 800
grid = true

[android]
serial = "emulator-5554"
"#,
        )
        .unwrap();
        assert_eq!(cfg.target, Target::Android);
        assert_eq!(cfg.mode, Mode::Observe);
        assert_eq!(cfg.max_edge, 800);
        assert!(cfg.grid_default);
        assert_eq!(cfg.android.serial, "emulator-5554");
        assert_eq!(cfg.effective_target(), Target::Android);
    }

    #[test]
    fn unknown_keys_and_bad_values_are_errors() {
        let mut cfg = Config::default();
        assert!(cfg.apply_toml("bogus = 1").is_err());
        assert!(cfg.apply_toml("target = \"ios\"").is_err());
        cfg.max_edge = 10;
        assert!(cfg.validate().is_err());
    }

    #[test]
    fn auto_target_prefers_configured_device() {
        let mut cfg = Config::default();
        cfg.harmony.target = "abc".into();
        if !cfg!(any(target_os = "android", target_env = "ohos")) {
            assert_eq!(cfg.effective_target(), Target::Harmony);
        }
    }
}

//! Screenshot geometry and the image pipeline.
//!
//! A [`Frame`] is the image the model last saw: `shot_w × shot_h` pixels
//! downscaled from a `dev_w × dev_h` capture. All model coordinates are in
//! shot space; [`Frame::to_device`] maps them back. A [`Zoom`] is a crop of
//! the same capture re-encoded at full budget; coordinates given in zoom
//! space are mapped through [`Zoom::to_frame`] first.

use std::io::Cursor;

use image::{DynamicImage, GenericImageView, ImageFormat, Rgb, RgbImage, imageops::FilterType};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Frame {
    pub shot_w: u32,
    pub shot_h: u32,
    pub dev_w: u32,
    pub dev_h: u32,
}

impl Frame {
    pub fn scale(&self) -> f64 {
        if self.shot_w == 0 {
            1.0
        } else {
            f64::from(self.dev_w) / f64::from(self.shot_w)
        }
    }

    /// Map shot-space coordinates to device pixels, rejecting points outside
    /// the frame (a small tolerance forgives off-by-one at the far edge).
    pub fn to_device(&self, x: f64, y: f64) -> Result<(f64, f64), String> {
        let (w, h) = (f64::from(self.shot_w), f64::from(self.shot_h));
        if !x.is_finite() || !y.is_finite() || x < -0.5 || y < -0.5 || x > w + 0.5 || y > h + 0.5 {
            return Err(format!(
                "point ({x}, {y}) is outside the current frame {}x{}; take a new computer_screenshot or use coordinates from the last one",
                self.shot_w, self.shot_h
            ));
        }
        let sx = f64::from(self.dev_w) / w;
        let sy = f64::from(self.dev_h) / h;
        let dx = (x * sx).clamp(0.0, f64::from(self.dev_w.saturating_sub(1)));
        let dy = (y * sy).clamp(0.0, f64::from(self.dev_h.saturating_sub(1)));
        Ok((dx, dy))
    }

    pub fn describe(&self) -> String {
        if self.shot_w == self.dev_w && self.shot_h == self.dev_h {
            format!("frame: {}x{} (device {}x{}, scale 1)", self.shot_w, self.shot_h, self.dev_w, self.dev_h)
        } else {
            format!(
                "frame: {}x{} (device {}x{}, scale {:.3})",
                self.shot_w,
                self.shot_h,
                self.dev_w,
                self.dev_h,
                self.scale()
            )
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Zoom {
    /// Region in frame (shot) space.
    pub x: u32,
    pub y: u32,
    pub w: u32,
    pub h: u32,
    /// Size of the zoomed image the model saw.
    pub out_w: u32,
    pub out_h: u32,
}

impl Zoom {
    /// Map zoom-image coordinates to frame coordinates.
    pub fn to_frame(&self, zx: f64, zy: f64) -> Result<(f64, f64), String> {
        let (w, h) = (f64::from(self.out_w), f64::from(self.out_h));
        if !zx.is_finite() || !zy.is_finite() || zx < -0.5 || zy < -0.5 || zx > w + 0.5 || zy > h + 0.5 {
            return Err(format!(
                "point ({zx}, {zy}) is outside the current zoom image {}x{}",
                self.out_w, self.out_h
            ));
        }
        let fx = f64::from(self.x) + zx * f64::from(self.w) / w;
        let fy = f64::from(self.y) + zy * f64::from(self.h) / h;
        Ok((fx, fy))
    }

    pub fn describe(&self) -> String {
        format!(
            "zoom: {}x{} image of frame region x={}..{} y={}..{} (pass frame=\"zoom\" to act on zoom coordinates, or convert: frame_x = {} + zoom_x * {:.3}, frame_y = {} + zoom_y * {:.3})",
            self.out_w,
            self.out_h,
            self.x,
            self.x + self.w,
            self.y,
            self.y + self.h,
            self.x,
            f64::from(self.w) / f64::from(self.out_w),
            self.y,
            f64::from(self.h) / f64::from(self.out_h)
        )
    }
}

pub fn decode(bytes: &[u8]) -> Result<DynamicImage, String> {
    image::load_from_memory(bytes).map_err(|e| format!("failed to decode screenshot: {e}"))
}

pub fn encode_png(img: &RgbImage) -> Result<Vec<u8>, String> {
    let mut buf = Cursor::new(Vec::new());
    DynamicImage::ImageRgb8(img.clone())
        .write_to(&mut buf, ImageFormat::Png)
        .map_err(|e| format!("failed to encode png: {e}"))?;
    Ok(buf.into_inner())
}

fn fit(w: u32, h: u32, max_edge: u32) -> (u32, u32) {
    let longest = w.max(h);
    if longest <= max_edge || longest == 0 {
        return (w, h);
    }
    let ratio = f64::from(max_edge) / f64::from(longest);
    (
        ((f64::from(w) * ratio).round() as u32).max(1),
        ((f64::from(h) * ratio).round() as u32).max(1),
    )
}

/// Downscale a capture to `max_edge`, optionally overlay a labeled grid, and
/// return PNG bytes plus the resulting frame geometry.
pub fn prepare(capture: &[u8], max_edge: u32, grid: bool) -> Result<(Vec<u8>, Frame), String> {
    let img = decode(capture)?;
    let (dev_w, dev_h) = img.dimensions();
    if dev_w == 0 || dev_h == 0 {
        return Err("screenshot is empty".to_string());
    }
    let (shot_w, shot_h) = fit(dev_w, dev_h, max_edge);
    let mut rgb = if (shot_w, shot_h) == (dev_w, dev_h) {
        img.to_rgb8()
    } else {
        img.resize_exact(shot_w, shot_h, FilterType::CatmullRom).to_rgb8()
    };
    if grid {
        draw_grid(&mut rgb);
    }
    let png = encode_png(&rgb)?;
    Ok((png, Frame { shot_w, shot_h, dev_w, dev_h }))
}

/// Crop `region` (frame space) out of the capture and scale it to `max_edge`.
pub fn zoom(
    capture: &[u8],
    frame: &Frame,
    region: (u32, u32, u32, u32),
    max_edge: u32,
) -> Result<(Vec<u8>, Zoom), String> {
    let (x, y, w, h) = region;
    if w < 8 || h < 8 {
        return Err("zoom region must be at least 8x8 frame pixels".to_string());
    }
    if x.saturating_add(w) > frame.shot_w || y.saturating_add(h) > frame.shot_h {
        return Err(format!(
            "zoom region x={x} y={y} w={w} h={h} exceeds the frame {}x{}",
            frame.shot_w, frame.shot_h
        ));
    }
    let img = decode(capture)?;
    let sx = f64::from(frame.dev_w) / f64::from(frame.shot_w);
    let sy = f64::from(frame.dev_h) / f64::from(frame.shot_h);
    let cx = ((f64::from(x) * sx).floor() as u32).min(frame.dev_w - 1);
    let cy = ((f64::from(y) * sy).floor() as u32).min(frame.dev_h - 1);
    let cw = ((f64::from(w) * sx).ceil() as u32).clamp(1, frame.dev_w - cx);
    let ch = ((f64::from(h) * sy).ceil() as u32).clamp(1, frame.dev_h - cy);
    let cropped = img.crop_imm(cx, cy, cw, ch);
    // Scale so the longest edge hits the budget (upscaling small regions
    // helps the model read fine text).
    let longest = cw.max(ch);
    let ratio = f64::from(max_edge) / f64::from(longest);
    let out_w = ((f64::from(cw) * ratio).round() as u32).max(1);
    let out_h = ((f64::from(ch) * ratio).round() as u32).max(1);
    let filter = if ratio > 1.0 { FilterType::Lanczos3 } else { FilterType::CatmullRom };
    let rgb = cropped.resize_exact(out_w, out_h, filter).to_rgb8();
    let png = encode_png(&rgb)?;
    Ok((png, Zoom { x, y, w, h, out_w, out_h }))
}

/// Pick a grid step that yields roughly 6-12 lines across the wider side.
fn grid_step(width: u32) -> u32 {
    for step in [50u32, 100, 200, 250, 500] {
        if width / step <= 12 {
            return step;
        }
    }
    500
}

const GRID_COLOR: Rgb<u8> = Rgb([255, 0, 200]);
const LABEL_COLOR: Rgb<u8> = Rgb([255, 255, 0]);
const OUTLINE_COLOR: Rgb<u8> = Rgb([0, 0, 0]);

fn draw_grid(img: &mut RgbImage) {
    let (w, h) = img.dimensions();
    let step = grid_step(w.max(h));
    let mut x = step;
    while x < w {
        for yy in 0..h {
            // Dashed vertical line so content stays readable.
            if yy % 6 < 4 {
                img.put_pixel(x, yy, GRID_COLOR);
            }
        }
        draw_label(img, x + 2, 2, &x.to_string());
        x += step;
    }
    let mut y = step;
    while y < h {
        for xx in 0..w {
            if xx % 6 < 4 {
                img.put_pixel(xx, y, GRID_COLOR);
            }
        }
        draw_label(img, 2, y + 2, &y.to_string());
        y += step;
    }
}

/// 3x5 bitmap digits, drawn at 2x with a 1px outline.
const DIGITS: [[u8; 5]; 10] = [
    [0b111, 0b101, 0b101, 0b101, 0b111],
    [0b010, 0b110, 0b010, 0b010, 0b111],
    [0b111, 0b001, 0b111, 0b100, 0b111],
    [0b111, 0b001, 0b111, 0b001, 0b111],
    [0b101, 0b101, 0b111, 0b001, 0b001],
    [0b111, 0b100, 0b111, 0b001, 0b111],
    [0b111, 0b100, 0b111, 0b101, 0b111],
    [0b111, 0b001, 0b001, 0b001, 0b001],
    [0b111, 0b101, 0b111, 0b101, 0b111],
    [0b111, 0b101, 0b111, 0b001, 0b111],
];

fn draw_label(img: &mut RgbImage, x0: u32, y0: u32, text: &str) {
    const SCALE: u32 = 2;
    let (w, h) = img.dimensions();
    let mut cursor = x0;
    for ch in text.chars() {
        let Some(digit) = ch.to_digit(10) else { continue };
        let glyph = DIGITS[digit as usize];
        // Outline pass then fill pass.
        for pass in 0..2 {
            for (row, bits) in glyph.iter().enumerate() {
                for col in 0..3u32 {
                    if bits & (0b100 >> col) == 0 {
                        continue;
                    }
                    for dy in 0..SCALE {
                        for dx in 0..SCALE {
                            let px = cursor + col * SCALE + dx;
                            let py = y0 + row as u32 * SCALE + dy;
                            if pass == 0 {
                                for (ox, oy) in [(-1i64, 0i64), (1, 0), (0, -1), (0, 1)] {
                                    let (qx, qy) = (px as i64 + ox, py as i64 + oy);
                                    if qx >= 0 && qy >= 0 && (qx as u32) < w && (qy as u32) < h {
                                        img.put_pixel(qx as u32, qy as u32, OUTLINE_COLOR);
                                    }
                                }
                            } else if px < w && py < h {
                                img.put_pixel(px, py, LABEL_COLOR);
                            }
                        }
                    }
                }
            }
        }
        cursor += 4 * SCALE;
    }
}

#[cfg(test)]
pub(crate) fn synthetic_png(w: u32, h: u32) -> Vec<u8> {
    let img = RgbImage::from_fn(w, h, |x, y| Rgb([(x % 256) as u8, (y % 256) as u8, 128]));
    encode_png(&img).unwrap()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn to_device_scales_and_bounds() {
        let frame = Frame { shot_w: 1024, shot_h: 640, dev_w: 2560, dev_h: 1600 };
        assert_eq!(frame.to_device(512.0, 320.0).unwrap(), (1280.0, 800.0));
        assert_eq!(frame.to_device(0.0, 0.0).unwrap(), (0.0, 0.0));
        let (x, y) = frame.to_device(1024.0, 640.0).unwrap();
        assert_eq!((x, y), (2559.0, 1599.0));
        assert!(frame.to_device(1100.0, 10.0).is_err());
        assert!(frame.to_device(-3.0, 10.0).is_err());
        assert!((frame.scale() - 2.5).abs() < 1e-9);
    }

    #[test]
    fn zoom_maps_back_into_frame_space() {
        let zoom = Zoom { x: 100, y: 50, w: 200, h: 100, out_w: 1024, out_h: 512 };
        assert_eq!(zoom.to_frame(0.0, 0.0).unwrap(), (100.0, 50.0));
        assert_eq!(zoom.to_frame(1024.0, 512.0).unwrap(), (300.0, 150.0));
        assert_eq!(zoom.to_frame(512.0, 256.0).unwrap(), (200.0, 100.0));
        assert!(zoom.to_frame(2000.0, 0.0).is_err());
    }

    #[test]
    fn prepare_downscales_to_budget_and_keeps_aspect() {
        let capture = synthetic_png(2000, 1000);
        let (png, frame) = prepare(&capture, 1024, false).unwrap();
        assert_eq!(frame, Frame { shot_w: 1024, shot_h: 512, dev_w: 2000, dev_h: 1000 });
        let decoded = decode(&png).unwrap();
        assert_eq!(decoded.dimensions(), (1024, 512));
    }

    #[test]
    fn prepare_leaves_small_captures_alone_and_grid_keeps_size() {
        let capture = synthetic_png(640, 480);
        let (png, frame) = prepare(&capture, 1024, true).unwrap();
        assert_eq!(frame.shot_w, 640);
        assert_eq!(frame.shot_h, 480);
        let decoded = decode(&png).unwrap().to_rgb8();
        assert_eq!(decoded.dimensions(), (640, 480));
        // A grid line was painted at x=100.
        assert_eq!(*decoded.get_pixel(100, 0), GRID_COLOR);
    }

    #[test]
    fn zoom_crops_and_upscales_region() {
        let capture = synthetic_png(2000, 1000);
        let frame = Frame { shot_w: 1000, shot_h: 500, dev_w: 2000, dev_h: 1000 };
        let (png, zoom) = zoom(&capture, &frame, (100, 100, 200, 100), 800).unwrap();
        assert_eq!((zoom.out_w, zoom.out_h), (800, 400));
        assert_eq!(decode(&png).unwrap().dimensions(), (800, 400));
        assert!(zoom.describe().contains("x=100..300"));
        assert!(super::zoom(&capture, &frame, (900, 0, 200, 100), 800).is_err());
        assert!(super::zoom(&capture, &frame, (0, 0, 4, 4), 800).is_err());
    }

    #[test]
    fn grid_step_scales_with_width() {
        assert_eq!(grid_step(640), 100);
        assert_eq!(grid_step(1024), 100);
        assert_eq!(grid_step(2048), 200);
    }
}

