//! Command line: `serve` (stdio MCP), plus operator diagnostics.

use std::path::PathBuf;

use crate::config::{Config, Mode, Target};

pub const USAGE: &str = "\
codewhale-computer-use — screenshots and input for Codewhale computer use

USAGE:
  codewhale-computer-use <COMMAND> [OPTIONS]

COMMANDS:
  serve                 Run the stdio MCP server (what the plugin bundle launches)
  doctor                Print target diagnostics and exit
  screenshot            Capture the screen to a PNG file (--out PATH, --grid)
  call <TOOL> [JSON]    Invoke one tool directly, e.g. call computer_click '{\"x\":10,\"y\":20}'
  tools                 Print the MCP tool catalog as JSON
  devices               List attached adb/hdc devices
  help, --help          Show this text
  --version             Show the version

OPTIONS (all commands):
  --config PATH         Config file (default ~/.codewhale/computer-use.toml)
  --target T            auto | desktop | android | harmony
  --mode M              act | observe
  --serial S            Android device serial (adb -s)
  --hdc-target K        HarmonyOS target key (hdc -t)
  --max-edge N          Longest screenshot edge in pixels (256..2048)
  --grid                Overlay a coordinate grid on screenshots
  --out PATH            (screenshot/call) where to write the returned image
";

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Command {
    Serve,
    Doctor,
    Screenshot,
    Call { tool: String, args: String },
    Tools,
    Devices,
    Help,
    Version,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Cli {
    pub command: Command,
    pub config_path: Option<PathBuf>,
    pub target: Option<Target>,
    pub mode: Option<Mode>,
    pub serial: Option<String>,
    pub hdc_target: Option<String>,
    pub max_edge: Option<u32>,
    pub grid: bool,
    pub out: Option<PathBuf>,
}

pub fn parse(args: &[String]) -> Result<Cli, String> {
    let mut cli = Cli {
        command: Command::Help,
        config_path: None,
        target: None,
        mode: None,
        serial: None,
        hdc_target: None,
        max_edge: None,
        grid: false,
        out: None,
    };
    let mut positionals: Vec<String> = Vec::new();
    let mut iter = args.iter();
    while let Some(arg) = iter.next() {
        let mut value_for = |name: &str| -> Result<String, String> {
            iter.next().cloned().ok_or_else(|| format!("{name} requires a value"))
        };
        match arg.as_str() {
            "--config" => cli.config_path = Some(PathBuf::from(value_for("--config")?)),
            "--target" => cli.target = Some(Target::parse(&value_for("--target")?)?),
            "--mode" => cli.mode = Some(Mode::parse(&value_for("--mode")?)?),
            "--serial" => cli.serial = Some(value_for("--serial")?),
            "--hdc-target" => cli.hdc_target = Some(value_for("--hdc-target")?),
            "--max-edge" => {
                let raw = value_for("--max-edge")?;
                cli.max_edge = Some(raw.parse().map_err(|_| format!("--max-edge must be a number, got `{raw}`"))?);
            }
            "--out" | "-o" => cli.out = Some(PathBuf::from(value_for("--out")?)),
            "--grid" => cli.grid = true,
            "--help" | "-h" | "help" => cli.command = Command::Help,
            "--version" | "-V" => cli.command = Command::Version,
            other if other.starts_with('-') => return Err(format!("unknown option `{other}`")),
            other => positionals.push(other.to_string()),
        }
    }
    if matches!(cli.command, Command::Help | Command::Version) && positionals.is_empty() {
        return Ok(cli);
    }
    let Some(first) = positionals.first() else {
        return Ok(cli);
    };
    cli.command = match first.as_str() {
        "serve" => Command::Serve,
        "doctor" | "info" => Command::Doctor,
        "screenshot" | "shot" => Command::Screenshot,
        "tools" => Command::Tools,
        "devices" => Command::Devices,
        "call" => {
            let tool = positionals.get(1).cloned().ok_or_else(|| "call requires a tool name".to_string())?;
            let args = positionals.get(2).cloned().unwrap_or_else(|| "{}".to_string());
            Command::Call { tool, args }
        }
        "help" => Command::Help,
        other => return Err(format!("unknown command `{other}`\n\n{USAGE}")),
    };
    Ok(cli)
}

impl Cli {
    /// Build the effective config: file, then explicit flags.
    pub fn config(&self) -> Result<Config, String> {
        let mut cfg = Config::load(self.config_path.as_deref())?;
        if let Some(target) = self.target {
            cfg.target = target;
        }
        if let Some(mode) = self.mode {
            cfg.mode = mode;
        }
        if let Some(serial) = &self.serial {
            cfg.android.serial = serial.clone();
        }
        if let Some(key) = &self.hdc_target {
            cfg.harmony.target = key.clone();
        }
        if let Some(max_edge) = self.max_edge {
            cfg.max_edge = max_edge;
        }
        if self.grid {
            cfg.grid_default = true;
        }
        cfg.validate()?;
        Ok(cfg)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn args(list: &[&str]) -> Vec<String> {
        list.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn parses_commands_and_options() {
        let cli = parse(&args(&["serve", "--target", "android", "--serial", "abc", "--mode", "observe"])).unwrap();
        assert_eq!(cli.command, Command::Serve);
        assert_eq!(cli.target, Some(Target::Android));
        assert_eq!(cli.serial.as_deref(), Some("abc"));
        assert_eq!(cli.mode, Some(Mode::Observe));
        let cli = parse(&args(&["call", "computer_click", "{\"x\":1}", "--out", "a.png"])).unwrap();
        assert_eq!(cli.command, Command::Call { tool: "computer_click".into(), args: "{\"x\":1}".into() });
        assert_eq!(cli.out, Some(PathBuf::from("a.png")));
        assert_eq!(parse(&args(&[])).unwrap().command, Command::Help);
        assert_eq!(parse(&args(&["--version"])).unwrap().command, Command::Version);
        assert!(parse(&args(&["bogus"])).is_err());
        assert!(parse(&args(&["serve", "--max-edge", "x"])).is_err());
        assert!(parse(&args(&["call"])).is_err());
    }

    #[test]
    fn flags_override_config() {
        let cli = parse(&args(&["doctor", "--config", "/nonexistent/none.toml", "--max-edge", "800", "--grid"])).unwrap();
        let cfg = cli.config().unwrap();
        assert_eq!(cfg.max_edge, 800);
        assert!(cfg.grid_default);
    }
}

//! Computer-use MCP server for Codewhale.
//!
//! Screenshots and input on macOS, Windows, Linux (including HarmonyOS PC),
//! Android (`adb`), and HarmonyOS/OpenHarmony (`hdc`), spoken over stdio MCP
//! (`2024-11-05`) to the Codewhale plugin runtime. See
//! `docs/design/COMPUTER_USE_PLUGIN.md` and `docs/COMPUTER_USE.md`.

pub mod cli;
pub mod config;
pub mod driver;
pub mod drivers;
pub mod frame;
pub mod keys;
pub mod mcp;
pub mod process;
pub mod session;

use std::io::Write;

use cli::Command;
use session::Session;

/// Entry point shared by the standalone binary and `codewhale computer-use`.
/// Returns the process exit code.
pub fn run(args: Vec<String>) -> i32 {
    match run_inner(&args) {
        Ok(code) => code,
        Err(message) => {
            eprintln!("codewhale-computer-use: {message}");
            2
        }
    }
}

fn run_inner(args: &[String]) -> Result<i32, String> {
    let cli = cli::parse(args)?;
    match &cli.command {
        Command::Help => {
            print!("{}", cli::USAGE);
            return Ok(0);
        }
        Command::Version => {
            println!("{} {}", mcp::SERVER_NAME, mcp::SERVER_VERSION);
            return Ok(0);
        }
        Command::Tools => {
            println!("{}", serde_json::to_string_pretty(&session::tool_catalog()).map_err(|e| e.to_string())?);
            return Ok(0);
        }
        _ => {}
    }
    let cfg = cli.config()?;
    let driver = match drivers::select_driver(&cfg) {
        Ok(driver) => driver,
        Err(e) if cli.command == Command::Serve => {
            // Keep serving so the model gets an actionable error from
            // computer_info instead of a dead MCP server.
            eprintln!("codewhale-computer-use: driver unavailable: {e}");
            Box::new(UnavailableDriver { message: e.to_string() })
        }
        Err(e) => return Err(e.to_string()),
    };
    let mut session = Session::new(driver, cfg);
    match cli.command {
        Command::Serve => {
            let stdin = std::io::stdin();
            let stdout = std::io::stdout();
            let code = mcp::McpServer::new(session).serve(stdin.lock(), stdout.lock());
            Ok(code)
        }
        Command::Doctor => {
            let info = session.call("computer_info", &serde_json::Value::Null);
            println!("{}", info.text);
            let devices = session.call("computer_devices", &serde_json::Value::Null);
            println!("{}", devices.text);
            println!("tools: {}", session::TOOL_NAMES.join(", "));
            Ok(if info.is_error { 1 } else { 0 })
        }
        Command::Devices => {
            let out = session.call("computer_devices", &serde_json::Value::Null);
            println!("{}", out.text);
            Ok(if out.is_error { 1 } else { 0 })
        }
        Command::Screenshot => {
            let out = session.call("computer_screenshot", &serde_json::json!({ "grid": cli.grid }));
            emit_outcome(&out, cli.out.as_deref().or(Some(std::path::Path::new("screenshot.png"))))
        }
        Command::Call { tool, args } => {
            let parsed: serde_json::Value = serde_json::from_str(&args).map_err(|e| format!("tool arguments must be JSON: {e}"))?;
            let out = session.call(&tool, &parsed);
            emit_outcome(&out, cli.out.as_deref())
        }
        Command::Help | Command::Version | Command::Tools => unreachable!("handled above"),
    }
}

fn emit_outcome(out: &session::ToolOutcome, image_path: Option<&std::path::Path>) -> Result<i32, String> {
    let mut stdout = std::io::stdout().lock();
    writeln!(stdout, "{}", out.text).map_err(|e| e.to_string())?;
    if let Some(png) = &out.image_png {
        match image_path {
            Some(path) => {
                std::fs::write(path, png).map_err(|e| format!("failed to write {}: {e}", path.display()))?;
                writeln!(stdout, "image: {} ({} bytes)", path.display(), png.len()).map_err(|e| e.to_string())?;
            }
            None => writeln!(stdout, "image: {} bytes (pass --out PATH to save it)", png.len()).map_err(|e| e.to_string())?,
        }
    }
    Ok(if out.is_error { 1 } else { 0 })
}

/// Placeholder driver used when no backend could start: every call returns
/// the startup error so the model (and operator) see the real cause.
struct UnavailableDriver {
    message: String,
}

impl UnavailableDriver {
    fn err<T>(&self) -> Result<T, driver::DriverError> {
        Err(driver::DriverError::Unavailable(self.message.clone()))
    }
}

impl driver::Driver for UnavailableDriver {
    fn info(&mut self) -> Result<driver::TargetInfo, driver::DriverError> {
        self.err()
    }
    fn screenshot(&mut self) -> Result<driver::RawFrame, driver::DriverError> {
        self.err()
    }
    fn move_to(&mut self, _p: driver::Point) -> Result<(), driver::DriverError> {
        self.err()
    }
    fn click(&mut self, _p: driver::Point, _b: driver::Button, _c: u32, _h: u64) -> Result<(), driver::DriverError> {
        self.err()
    }
    fn drag(&mut self, _f: driver::Point, _t: driver::Point, _d: u64) -> Result<(), driver::DriverError> {
        self.err()
    }
    fn scroll(&mut self, _p: driver::Point, _d: driver::ScrollDir, _a: u32) -> Result<(), driver::DriverError> {
        self.err()
    }
    fn type_text(&mut self, _t: &str) -> Result<(), driver::DriverError> {
        self.err()
    }
    fn key(&mut self, _c: &keys::KeyCombo) -> Result<(), driver::DriverError> {
        self.err()
    }
    fn ui_tree(&mut self) -> Result<Vec<driver::UiNode>, driver::DriverError> {
        self.err()
    }
    fn app(&mut self, _a: driver::AppAction<'_>) -> Result<String, driver::DriverError> {
        self.err()
    }
    fn devices(&mut self) -> Result<String, driver::DriverError> {
        self.err()
    }
}

